    'sw/main.js': utf8.encode('// sw'),
    'panel/panel.html': utf8.encode('<html>panel</html>'),
    'panel/app/index.html': utf8.encode(flutterIndexHtml),
    'panel/app/main.dart.js': utf8.encode('// app'),
