    test('valid single-manifest package passes (AC1 GREEN shape)', () {
      final zip = writeZip('valid.zip', validPackage());
      final res = runGuard(['check', zip.path]);
      expect(
        res.exitCode,
        0,
        reason: 'stdout: ${res.stdout}\nstderr: ${res.stderr}',
      );
    });

